def transform(grid):
    counts = {3: 0, 2: 0}
    for row in grid:
        for value in row:
            if value in counts:
                counts[value] += 1
    n3 = min(3, (counts[3] + 3) // 4)
    n2 = min(3, (counts[2] + 3) // 4)
    cells = [3] * n3 + [2] * n2
    cells += [0] * (6 - len(cells))
    return [cells[:3], cells[3:]]
